def transform(grid):
    from collections import Counter
    # Count frequencies of all colors
    counts = Counter()
    for row in grid:
        for cell in row:
            counts[cell] += 1

    # Find background color (most frequent)
    bg_color = max(counts, key=counts.get)

    # Map: background → 0, color 5 → background color, other colors → 0
    output_grid = []
    for row in grid:
        new_row = []
        for cell in row:
            if cell == bg_color:
                new_row.append(0)
            elif cell == 5:
                new_row.append(bg_color)
            else:
                new_row.append(0)
        output_grid.append(new_row)
    return output_grid
